from PIL import Image
im = Image.open("/tmp/screen_full.png")
pixels = im.load()
# Let us inspect y ranges with blue pixels
y_counts = {}
for y in range(300, 900):
    for x in range(500, 1000):
        r, g, b = pixels[x, y][:3]
        if b > 140 and b > r + 50 and b > g + 20:
            y_counts[y] = y_counts.get(y, 0) + 1

# find connected vertical bands
bands = []
cur = []
for y in range(300, 900):
    if y_counts.get(y, 0) > 5:
        cur.append(y)
    else:
        if cur:
            bands.append((min(cur), max(cur), sum(y_counts[yy] for yy in cur)))
            cur = []
for b in bands:
    print("Band:", b)
'

